import { test, expect } from '@playwright/test';

test.describe('File Download - Previously Uploaded File', () => {
  const testFilePath = 'test-files/sample.txt';
  const testFileName = 'sample.txt';
  const testFileContent = 'This is a test file for download functionality';

  test.beforeEach(async ({ page }) => {
    // Navigate to the file management page
    await page.goto('/files');

    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should display previously uploaded files in the file list', async ({ page }) => {
    // Verify that the file list is visible
    const fileList = page.getByRole('list', { name: /uploaded files/i });
    await expect(fileList).toBeVisible();

    // Check if the previously uploaded file is displayed
    const fileItem = page.getByRole('listitem').filter({ hasText: testFileName });
    await expect(fileItem).toBeVisible();
  });

  test('should download a previously uploaded file successfully', async ({ page, context }) => {
    // Find the file in the list
    const fileRow = page.getByRole('row').filter({ hasText: testFileName });
    await expect(fileRow).toBeVisible();

    // Click the download button for the file
    const downloadButton = fileRow.getByRole('button', { name: /download/i });
    await expect(downloadButton).toBeVisible();

    // Start waiting for the download before clicking
    const downloadPromise = context.waitForEvent('download');
    await downloadButton.click();

    // Wait for the download to complete
    const download = await downloadPromise;

    // Verify the download was successful
    expect(download.suggestedFilename()).toBe(testFileName);

    // Verify the file path exists
    const path = await download.path();
    expect(path).toBeTruthy();
  });

  test('should display file details when clicking on a file', async ({ page }) => {
    // Find the file in the list
    const fileLink = page.getByRole('link', { name: testFileName });
    await expect(fileLink).toBeVisible();

    // Click on the file to view details
    await fileLink.click();

    // Verify file details are displayed
    const fileNameHeading = page.getByRole('heading', { name: testFileName });
    await expect(fileNameHeading).toBeVisible();

    // Verify file size is displayed
    const fileSizeText = page.getByText(/file size:/i);
    await expect(fileSizeText).toBeVisible();

    // Verify upload date is displayed
    const uploadDateText = page.getByText(/uploaded on:/i);
    await expect(uploadDateText).toBeVisible();
  });

  test('should allow downloading file from the file details page', async ({ page, context }) => {
    // Navigate to file details
    const fileLink = page.getByRole('link', { name: testFileName });
    await fileLink.click();

    // Wait for details page to load
    await page.waitForLoadState('networkidle');

    // Find and click the download button on details page
    const downloadButton = page.getByRole('button', { name: /download file/i });
    await expect(downloadButton).toBeVisible();

    // Start waiting for download
    const downloadPromise = context.waitForEvent('download');
    await downloadButton.click();

    // Wait for download to complete
    const download = await downloadPromise;

    // Verify download details
    expect(download.suggestedFilename()).toBe(testFileName);
    expect(download.suggestedFilename()).toContain('.txt');
  });

  test('should show error message when download fails', async ({ page }) => {
    // Find a file that might fail to download (simulate by looking for a specific file)
    const fileRow = page.getByRole('row').filter({ hasText: testFileName });

    // Intercept the download request to simulate failure
    await page.route('**/api/files/download/**', route => {
      route.abort('failed');
    });

    // Click download button
    const downloadButton = fileRow.getByRole('button', { name: /download/i });
    await downloadButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText(/download failed|error/i);
  });

  test('should maintain file list after successful download', async ({ page, context }) => {
    // Get initial file count
    const fileItems = page.getByRole('listitem');
    const initialCount = await fileItems.count();

    // Download a file
    const fileRow = page.getByRole('row').filter({ hasText: testFileName });
    const downloadButton = fileRow.getByRole('button', { name: /download/i });

    const downloadPromise = context.waitForEvent('download');
    await downloadButton.click();
    await downloadPromise;

    // Verify file list is still visible and unchanged
    const updatedFileItems = page.getByRole('listitem');
    const updatedCount = await updatedFileItems.count();
    expect(updatedCount).toBe(initialCount);

    // Verify the file is still in the list
    const fileItem = page.getByRole('listitem').filter({ hasText: testFileName });
    await expect(fileItem).toBeVisible();
  });
});
